import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

const $=id=>document.getElementById(id), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const canvas=$('world');
let renderer,scene,camera,clock,player,horse,horseMounted=false,started=false,paused=false,dialogueOpen=false,mapOpen=false,inventoryOpen=false;
let keys={},npcs=[],wildlife=[],bullets=[],dust=[],interactables=[],buildings=[],missionIndex=0,sideIndex=0,ammo=6,reserve=36,health=100,money=24,herbs=0,weapon=0,aiming=false,fireCooldown=0,toastTimer=0,dayTime=.38,weather=0,worldTime=0;
const worldSize=650,raycaster=new THREE.Raycaster(),mouse=new THREE.Vector2(0,0),tempV=new THREE.Vector3();
const mats={};
const campaign=[
['A Brother’s Shadow','Speak with Mara at the telegraph office.','Mara Bell','The wire went dead three nights ago. Thomas was sending from the north line. Sheriff Vale told me to forget I ever heard his name. I don’t forget things, Daniel.'],
['A Quiet Ledger','Search the sheriff’s office for Thomas’s arrest record.','Mara Bell','Vale keeps a second ledger in his desk. The front door is watched. Try the back, and keep your head down.'],
['Dust on the Trail','Ride to Mercer Ranch and ask old Silas about the riders.','Silas Mercer','Four riders came through before dawn. One wore a brass spur stamped with a coiled snake. Thomas had the same mark burned into a letter.'],
['The Brass Spur','Follow the tracks to the dry creek bed.','Silas Mercer','If they rode north, the wash will show it. Take your iron. The country’s gone mean.'],
['A Camp Gone Cold','Clear the outlaw camp and search their supplies.','Silas Mercer','A gang calling itself the Ash Vipers. They’re new to this county, but someone gave them a map.'],
['No Easy Answers','Return to Mara with the map you found.','Mara Bell','This is a survey of Bellweather Mine. Thomas thought the owners were moving something through the old workings.'],
['Bellweather','Reach the abandoned mine before sundown.','Mara Bell','There’s a service entrance east of the ridge. I’ll wait here. If you find him, bring him home.'],
['Below the Ridge','Search the mine office for the missing dispatch.','Mara Bell','The mine closed ten years ago. Why is the telegraph still running? Someone’s been using that tunnel.'],
['The Company Man','Confront foreman Harlan at the mine entrance.','Harlan Rusk','Your brother asked the wrong questions. The railroad men paid good money to keep those questions quiet.'],
['A Long Ride','Take the dispatch to Fort Carden.','Harlan Rusk','Captain Reddick signed the transport orders. He’s at the fort, east of the river.'],
['Fort Carden','Speak with Captain Reddick at the garrison.','Captain Reddick','I signed no such order. But that seal is real. Someone in my office is selling military routes.'],
['A Familiar Face','Find the quartermaster after dark.','Captain Reddick','Quartermaster Dole has been here twenty years. He knows every supply wagon and every name on the rolls.'],
['The False Trail','Ride to Red Wash and intercept the supply wagon.','Captain Reddick','Dole’s wagon leaves at first light. Don’t let it reach the canyon.'],
['Snake in the Grass','Bring the quartermaster to justice.','Captain Reddick','Dole has friends in the Ash Vipers. Be careful who you point that revolver at.'],
['A Brother’s Mark','Search the canyon hideout for Thomas’s journal.','Mara Bell','He left a mark on the canyon wall when we were children. Three scratches beneath the hawk. Look for it.'],
['The Empty Saddle','Ask rancher June about the rider seen heading west.','June Calder','A man matching Thomas’s description bought a fresh horse here. He wasn’t alone. He looked scared.'],
['Last Telegraph','Restore the relay at Pine Ridge station.','June Calder','The line runs through the forest now. If the relay works, Mara can trace the last signal.'],
['The Crossing','Defend the river crossing until the riders arrive.','Mara Bell','The message is clear: Thomas is alive. But the Vipers know we’re close. Hold the crossing.'],
['What Was Buried','Meet Thomas at the old church beyond the cemetery.','Thomas Mercer','Danny. I’m sorry. There’s something you need to know about Father, and the land deed he hid.'],
['A New Horizon','Decide what becomes of the Mercer land and the people who live on it.','Thomas Mercer','Whatever comes next, we face it together. No more running from the truth.']
];
const sideMissions=Array.from({length:30},(_,i)=>[
['The Missing Calf','Find the rancher’s calf near the creek.'],['A Sheriff’s Favor','Bring a wanted poster to the sheriff.'],['Sage for June','Gather wild sage for the ranch cook.'],['A Poker Debt','Win a hand at the Cinder Creek saloon.'],['The Lost Prospector','Find the prospector’s lantern in the hills.'],['Tracks in the Snow','Follow the wolf prints to the ridge.'],['Last Water','Deliver a canteen to the traveler.'],['A Grave Unmarked','Visit the lonely grave above town.'],['The Broken Wheel','Find a wagon spoke near the crossroads.'],['Night Watch','Protect the farm through the night.']][i%10]);
const names=['Mara Bell','Silas Mercer','June Calder','Sheriff Abram Vale','Elias Finch','Ruth Holloway','Tommy Pike','Ada Whitlock','Harlan Rusk','Nora Gray','Wesley Cobb','Inez Rojas','Caleb Dunn','Milo Sutter','Bea Larkin','Josiah Reed','Clara Voss','August Bell','Rafe Hollis','Della Crane','Hank Barlow','Etta June','Orin Moss','Lottie Webb'];
function makeMat(color,rough=1,metal=0){return new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});}
function box(w,h,d,mat,x=0,y=0,z=0,parent=scene){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cyl(rt,rb,h,mat,x=0,y=0,z=0,parent=scene,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function group(parent=scene,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g;}
function makeTexture(base,accent){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=base;ctx.fillRect(0,0,256,256);for(let i=0;i<1800;i++){const x=Math.random()*256,y=Math.random()*256,a=Math.random()*.15;ctx.fillStyle=Math.random()>.5?`rgba(255,230,180,${a})`:`rgba(35,24,16,${a})`;ctx.fillRect(x,y,Math.random()*3+1,Math.random()*2+1);}ctx.strokeStyle=accent;ctx.globalAlpha=.13;for(let i=0;i<35;i++){ctx.beginPath();ctx.moveTo(Math.random()*256,Math.random()*256);ctx.lineTo(Math.random()*256,Math.random()*256);ctx.stroke();}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(28,28);return t;}
function init(){
 try{
 renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;
 scene=new THREE.Scene();scene.background=new THREE.Color(0xb8a084);scene.fog=new THREE.FogExp2(0xb8a084,.0035);camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,.1,900);clock=new THREE.Clock();
 const hemi=new THREE.HemisphereLight(0xffdfb1,0x514333,1.12);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffd49a,3.0);sun.position.set(-90,140,-80);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;sun.shadow.bias=-.0002;scene.add(sun);scene.add(sun.target);scene.userData.sun=sun;scene.userData.hemi=hemi;
 mats.ground=new THREE.MeshStandardMaterial({map:makeTexture('#a98b62','#6c5a43'),roughness:1});mats.road=makeMat(0x876b4d);mats.wood=makeMat(0x68472e);mats.darkwood=makeMat(0x3e3024);mats.plaster=makeMat(0xb99b72);mats.red=makeMat(0x8e5140);mats.roof=makeMat(0x49382e);mats.green=makeMat(0x526044);mats.leaf=makeMat(0x68744b);mats.stone=makeMat(0x746b5d);mats.gold=makeMat(0xc29a56,.45,.25);mats.black=makeMat(0x201c19);mats.skin=makeMat(0xb47d58);mats.cloth=makeMat(0x43505a);mats.horse=makeMat(0x68452d);mats.white=makeMat(0xd4c5a5);
 makeTerrain();makeTown();makeLandmarks();makeNature();makeClouds();makeNPCs();makeWildlife();makePlayer();makeHorse();makeDust();setupEvents();updateMap();
 $('loading').style.opacity='0';setTimeout(()=>$('loading').classList.add('hidden'),650);
 animate();
 }catch(e){console.error(e);$('loading').classList.add('hidden');$('errorBanner').classList.remove('hidden');}
}
function makeTerrain(){
 const geo=new THREE.PlaneGeometry(worldSize,worldSize,80,80);geo.rotateX(-Math.PI/2);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);let y=Math.sin(x*.019)*1.8+Math.cos(z*.023)*1.6+Math.sin((x+z)*.012)*2.1;y+=Math.max(0,(Math.abs(x)-185)*.12)+Math.max(0,(-z-210)*.2);p.setY(i,y);}geo.computeVertexNormals();const ground=new THREE.Mesh(geo,mats.ground);ground.receiveShadow=true;scene.add(ground);
 // Settled dirt road, tracks and river
 const road=box(19,.12,460,mats.road,0,.08,-25);road.rotation.y=.1;const road2=box(11,.13,260,mats.road,90,.1,-65);road2.rotation.y=-.63;
 const riverMat=new THREE.MeshStandardMaterial({color:0x537a78,roughness:.22,metalness:.2,transparent:true,opacity:.83});const river=box(19,.13,475,riverMat,118,.05,-45);river.rotation.y=-.13;
 for(let x=-280;x<290;x+=3.1){for(const z of [-33,-28]){cyl(.13,.13,2.4,mats.darkwood,x,.7,z,scene,6).rotation.z=Math.PI/2;}}
 for(let i=0;i<40;i++){const x=-300+Math.random()*600,z=-285+Math.random()*570;if(Math.abs(x)<34||Math.abs(x-90)<28)continue;const hill=new THREE.Mesh(new THREE.IcosahedronGeometry(20+Math.random()*38,1),makeMat(i%3?0x85745b:0x71644f));hill.position.set(x,8+Math.random()*14,z);hill.scale.y=.35+Math.random()*.35;hill.receiveShadow=true;scene.add(hill);}
 // Distant mesa silhouettes
 for(let i=0;i<18;i++){const x=-320+i*38,z=-315-Math.random()*35,h=48+Math.random()*60;const m=new THREE.Mesh(new THREE.ConeGeometry(32+Math.random()*25,h,5),makeMat(i%2?0x786952:0x655b49));m.position.set(x,h*.38,z);m.rotation.y=Math.random()*2;scene.add(m);}
}
function makeBuilding(x,z,w,d,wall,style='town',label=''){
 const g=group(scene,x,0,z),h=style==='town'?5.8:4.7;const body=box(w,h,d,wall,0,h/2,0,g);const roofMat=style==='town'?mats.roof:mats.wood;
 const roof=new THREE.Mesh(new THREE.ConeGeometry(Math.max(w,d)*.78,2.5,4),roofMat);roof.position.y=h+1;roof.rotation.y=Math.PI/4;roof.scale.set(1,.66,Math.max(w,d)/Math.min(w,d));roof.castShadow=true;g.add(roof);
 const front=box(w*.27,2.8,.15,mats.darkwood,0,1.55,d/2+.1,g);front.position.z=d/2+.08;
 box(w*.12,2.1,.18,mats.wood,0,1.1,d/2+.2,g);const awning=box(w*.85,.35,1.4,style==='town'?mats.red:mats.green,0,3.5,d/2+.72,g);box(w*.88,.16,2.8,mats.wood,0,.2,d/2+.3,g);
 for(const sx of [-1,1]){box(.18,2.2,.2,mats.wood,sx*w*.34,1.15,d/2+.22,g);box(1.05,1.15,.12,mats.black,sx*w*.32,3.1,d/2+.1,g);box(.92,.08,.14,mats.wood,sx*w*.32,3.1,d/2+.18,g);box(.08,1,.14,mats.wood,sx*w*.32,3.1,d/2+.18,g);}
 const sign=box(Math.min(w*.8,5),.72,.13,mats.darkwood,0,h-1,d/2+.23,g);if(label){const cv=document.createElement('canvas');cv.width=512;cv.height=96;const c=cv.getContext('2d');c.fillStyle='#37271b';c.fillRect(0,0,512,96);c.fillStyle='#e2c38b';c.font='bold 34px Georgia';c.textAlign='center';c.fillText(label.toUpperCase(),256,61);const tx=new THREE.CanvasTexture(cv);const plane=new THREE.Mesh(new THREE.PlaneGeometry(Math.min(w*.8,5),.72),new THREE.MeshBasicMaterial({map:tx,transparent:true}));plane.position.set(0,h-1,d/2+.31);g.add(plane);}
 buildings.push({x,z,r:Math.max(w,d)*.65,label,group:g});return g;
}

