function makeTree(x,z,scale=1){const g=group(scene,x,0,z);cyl(.32*scale,.55*scale,3.8*scale,mats.wood,0,1.9*scale,0,g,7);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry((2.3-i*.35)*scale,1),i===1?mats.green:mats.leaf);crown.position.set((Math.random()-.5)*.8,3.6*scale+i*1.35*scale,(Math.random()-.5)*.6);crown.scale.y=1.1;crown.castShadow=true;g.add(crown);}return g;}
function makeNature(){
 for(let i=0;i<190;i++){const x=-310+Math.random()*620,z=-300+Math.random()*590;if(Math.abs(x)<85&&z>-145&&z<-35)continue;if(Math.abs(x-105)<24)continue;const r=Math.random();if(r<.52){const trunk=cyl(.1+Math.random()*.14,.25,.6+Math.random()*.8,mats.green,x,.3,z,scene,7);trunk.scale.set(1,1,1);const arms=3+Math.floor(Math.random()*3);for(let j=0;j<arms;j++){const h=1.7+Math.random()*2,arm=cyl(.07,.1,h,mats.green,x+Math.cos(j*2.1)*.38,.8+h/2,z+Math.sin(j*2.1)*.38,scene,6);arm.rotation.z=(Math.random()-.5)*.16;}}
 else if(r<.76)makeTree(x,z,.55+Math.random()*.55);else{const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.6+Math.random()*1.8,0),mats.stone);rock.position.set(x,.5,z);rock.scale.y=.55;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;scene.add(rock);}}
