 for(let i=0;i<22;i++){const x=202+(i%6)*5,z=-181+Math.floor(i/6)*5;box(.18,3,.22,mats.wood,x,1.5,z);box(5,.16,.18,mats.wood,x+2.5,1.15,z);box(5,.16,.18,mats.wood,x+2.5,2.1,z);}
