function makeClouds(){scene.userData.clouds=[];const cloudMat=new THREE.MeshStandardMaterial({color:0xf1dfc7,transparent:true,opacity:.38,roughness:1});for(let i=0;i<14;i++){const g=group(scene,-300+Math.random()*600,75+Math.random()*35,-280+Math.random()*550);for(let j=0;j<5;j++){const c=new THREE.Mesh(new THREE.SphereGeometry(7+Math.random()*9,8,6),cloudMat);c.scale.y=.25;c.position.set((Math.random()-.5)*20,(Math.random()-.5)*2,(Math.random()-.5)*10);g.add(c);}scene.userData.clouds.push(g);}}
function makeCowboy(x,z,options={}){
 const root=group(scene,x,0,z),coat=options.color||mats.cloth,scale=options.scale||1;
 const torso=box(.68*scale,1.05*scale,.4*scale,coat,0,1.35*scale,0,root),head=new THREE.Mesh(new THREE.SphereGeometry(.28*scale,10,8),mats.skin);head.position.set(0,2.1*scale,0);root.add(head);
 const neck=cyl(.12*scale,.14*scale,.3*scale,mats.skin,0,1.91*scale,0,root,7);neck.rotation.x=.1;
 for(const side of [-1,1]){const arm=cyl(.12*scale,.15*scale,.77*scale,coat,side*.44*scale,1.38*scale,0,root,7);arm.rotation.z=side*.19;const leg=cyl(.14*scale,.18*scale,.82*scale,mats.darkwood,side*.2*scale,.48*scale,0,root,7);}
 const brim=new THREE.Mesh(new THREE.CylinderGeometry(.42*scale,.42*scale,.09*scale,12),mats.darkwood);brim.position.set(0,2.38*scale,0);root.add(brim);const crown=new THREE.Mesh(new THREE.CylinderGeometry(.22*scale,.27*scale,.34*scale,9),options.hat||mats.wood);crown.position.set(0,2.57*scale,0);root.add(crown);
 if(options.player){const band=box(.68*scale,.12*scale,.42*scale,mats.gold,0,1.73*scale,.02,root);}
 root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});return {root,head,torso,arms:root.children.filter((c,i)=>i===3||i===4),phase:Math.random()*6.28,baseX:x,baseZ:z, ...options};
}
function makeNPCs(){
 const palettes=[0x49515a,0x697144,0x71463b,0x423b33,0x887355,0x394550,0x665342,0x765844].map(c=>makeMat(c));
 const fixed=[['Mara Bell',-14,-98,'Mara Bell'],['Silas Mercer',-158,35,'Silas Mercer'],['June Calder',-192,58,'June Calder'],['Sheriff Abram Vale',43,-94,'Sheriff Abram Vale'],['Harlan Rusk',181,67,'Harlan Rusk'],['Captain Reddick',219,-157,'Captain Reddick'],['Thomas Mercer',-265,105,'Thomas Mercer']];
 fixed.forEach((v,i)=>{const a=makeCowboy(v[1],v[2],{name:v[0],role:v[3],color:palettes[i%palettes.length],keyNpc:true,homeX:v[1],homeZ:v[2]});npcs.push(a);interactables.push(a);});
 for(let i=0;i<56;i++){let x,z;if(i<37){x=-62+Math.random()*140;z=-126+Math.random()*82;}else if(i<45){x=-218+Math.random()*63;z=25+Math.random()*60;}else{x=193+Math.random()*52;z=-176+Math.random()*48;}const a=makeCowboy(x,z,{name:names[(i+7)%names.length],role:['Ranch hand','Traveler','Shopkeeper','Teamster','Preacher','Gambler'][i%6],color:palettes[i%palettes.length],wander:true,homeX:x,homeZ:z});npcs.push(a);}
 // Six armed riders guard the Red Wash canyon camp.
 for(let i=0;i<7;i++){const x=236+Math.random()*25,z=84+Math.random()*27;const a=makeCowboy(x,z,{name:['Viper lookout','Viper rider','Ash Viper'][i%3],role:'outlaw',color:makeMat(0x302923),enemy:true,health:2,wander:true,homeX:x,homeZ:z});npcs.push(a);interactables.push(a);}
}
function makeAnimal(x,z,type='deer'){
 const g=group(scene,x,0,z),fur=makeMat(type==='deer'?0x9a704a:type==='wolf'?0x6a6259:type==='rabbit'?0x82725f:0x9c7951);const body=new THREE.Mesh(new THREE.SphereGeometry(type==='rabbit'?.34:.65,10,8),fur);body.scale.set(1,.74,1.55);body.position.y=type==='rabbit'?.38:.93;g.add(body);
 const neck=new THREE.Mesh(new THREE.SphereGeometry(type==='deer'?.29:.34,8,7),fur);neck.position.set(0,type==='deer'?1.26:1.04,.74);neck.scale.set(.7,1,1);g.add(neck);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),fur);head.position.set(0,type==='deer'?1.67:1.2,1.02);g.add(head);
 if(type==='deer')for(const s of [-1,1]){const ant=cyl(.035,.05,.6,mats.stone, s*.12,2.03,1.02,g,5);ant.rotation.z=s*.48;}
 for(let s of [-1,1])for(let q of [-1,1]){const leg=cyl(.07,.1,type==='rabbit'?.32:.65,fur,s*.24,type==='rabbit'?.22:.52,q*.48,g,6);leg.rotation.x=q*.05;}
 g.traverse(o=>{if(o.isMesh)o.castShadow=true;});scene.add(g);const a={root:g,type,health:1,phase:Math.random()*9,alive:true};wildlife.push(a);return a;
}
function makeWildlife(){const types=['deer','rabbit','wolf','coyote'];for(let i=0;i<32;i++){const x=-270+Math.random()*540,z=-260+Math.random()*520;if(Math.abs(x)<85&&z>-145&&z<-30)continue;makeAnimal(x,z,types[i%types.length]);}}
function makePlayer(){player=makeCowboy(0, -41,{player:true,color:makeMat(0x554039),hat:makeMat(0x302722)});player.root.rotation.y=Math.PI;player.speed=0;player.velocityY=0;player.yaw=Math.PI;player.health=100;player.crouch=false;}
function makeHorse(){const g=group(scene,8,0,-43),fur=makeMat(0x70472e);const body=new THREE.Mesh(new THREE.SphereGeometry(.75,12,10),fur);body.position.set(0,1.6,0);body.scale.set(.8,.83,1.5);g.add(body);const neck=new THREE.Mesh(new THREE.CylinderGeometry(.24,.38,1.1,10),fur);neck.position.set(0,2.05,.95);neck.rotation.x=-.48;g.add(neck);const head=new THREE.Mesh(new THREE.SphereGeometry(.3,10,8),fur);head.position.set(0,2.48,1.35);head.scale.set(.72,1.1,1.2);g.add(head);
 for(const s of [-1,1])for(const z of [-.85,.85]){const leg=cyl(.12,.16,1.1,fur,s*.46,.75,z,g,8);leg.userData.leg=true;}
 const mane=cyl(.16,.18,.9,mats.darkwood,0,2.52,.83,g,7);mane.rotation.x=-.6;box(.8,.16,.9,mats.wood,0,2.15,-.15,g);box(.72,.12,.34,mats.darkwood,0,2.28,-.38,g);const tail=cyl(.07,.1,.9,mats.darkwood,0,1.55,-1.35,g,6);tail.rotation.x=.3;
 g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});horse={root:g,health:100,stamina:100,bond:12,speed:0,phase:0,legs:g.children.filter(o=>o.userData.leg)};const ring=new THREE.Mesh(new THREE.TorusGeometry(1.25,.04,5,24),mats.gold);ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);}
function makeDust(){const geo=new THREE.BufferGeometry(),positions=new Float32Array(420*3);for(let i=0;i<420;i++){positions[i*3]=(Math.random()-.5)*400;positions[i*3+1]=Math.random()*26;positions[i*3+2]=(Math.random()-.5)*400;}geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const mat=new THREE.PointsMaterial({color:0xf3d7a4,size:.17,transparent:true,opacity:.35,depthWrite:false});const points=new THREE.Points(geo,mat);scene.add(points);scene.userData.dust=points;}

