const missionSites=[[-14,-98],[43,-94],[-158,35],[0,38],[239,95],[-14,-98],[183,72],[183,72],[180,68],[219,-157],[219,-157],[211,-155],[238,86],[235,85],[245,100],[-192,58],[-226,-176],[115,-2],[-25,-42],[-170,38]];
function currentMission(){return campaign[Math.min(missionIndex,campaign.length-1)];}
function startGame(continuing=false){if(continuing){try{const save=JSON.parse(localStorage.getItem('dustSave')||'{}');missionIndex=clamp(save.missionIndex||0,0,campaign.length-1);money=save.money||24;}catch{}}started=true;$('startScreen').classList.add('hidden');$('hud').classList.remove('hidden');if(matchMedia('(pointer:coarse)').matches)$('touchControls').classList.remove('hidden');showToast(continuing?'The trail picks up where you left it.':'Cinder Creek. The summer of 1891.');refreshHud();}
function refreshHud(){const m=currentMission();$('missionTitle').textContent=m[0];$('missionObjective').textContent=missionIndex===3?'Clear the Ash Vipers’ camp near Red Wash Canyon.':m[1];$('chapterLabel').textContent=missionIndex<5?'CHAPTER I':missionIndex<10?'CHAPTER II':missionIndex<15?'CHAPTER III':missionIndex<19?'CHAPTER IV':'EPILOGUE';$('missionProgress').style.width=`${Math.max(4,missionIndex/campaign.length*100)}%`;$('healthBar').style.width=`${health}%`;$('horseBar').style.width=`${horse.stamina}%`;$('ammoLabel').textContent=`${weapon?'▰ 12 / 48':'✦ '+ammo+' / '+reserve}`;$('moneyLabel').textContent=`$ ${money.toFixed(2)}`;$('herbCount').textContent=herbs;updateMap();}
function targetPosition(){const v=missionSites[Math.min(missionIndex,missionSites.length-1)];return new THREE.Vector3(v[0],0,v[1]);}
function updateMap(){if(!player)return;const pos=player.root.position;const xp=clamp((pos.x+320)/640*100,3,97),yp=clamp((pos.z+320)/640*100,3,97);$('mapPlayer').style.left=xp+'%';$('mapPlayer').style.top=yp+'%';const t=missionSites[Math.min(missionIndex,missionSites.length-1)];$('mapArt').querySelector('.mission-marker').style.left=clamp((t[0]+320)/640*100,3,97)+'%';$('mapArt').querySelector('.mission-marker').style.top=clamp((t[1]+320)/640*100,3,97)+'%';}
function showToast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.8;}
function openDialogue(name,text,onClose){dialogueOpen=true;$('speakerName').textContent=name;$('portrait').textContent=(name||'?').charAt(0);$('dialogueText').textContent=text;$('dialogue').classList.remove('hidden');$('dialogueContinue').onclick=()=>{$('dialogue').classList.add('hidden');dialogueOpen=false;if(onClose)onClose();};}
function finishMission(){if(missionIndex<campaign.length-1){missionIndex++;money+=8+Math.random()*12;localStorage.setItem('dustSave',JSON.stringify({missionIndex,money}));refreshHud();showToast('LEAD RECORDED · $'+(8+0).toFixed(2)+' REWARD');}else{showToast('THE MERCER STORY IS COMPLETE. THE FRONTIER IS YOURS.');$('missionObjective').textContent='The story is yours to continue. Explore the territory.';missionIndex=campaign.length-1;}}
function nearestThing(){let best=null,dist=5;const p=player.root.position;for(const n of npcs){if(n.dead||n.enemy&&n.health<=0)continue;const d=p.distanceTo(n.root.position);if(d<dist){best=n;dist=d;}}const dh=p.distanceTo(horse.root.position);if(dh<dist){best={horse:true,name:'Your horse',root:horse.root};dist=dh;}for(const item of interactables.filter(v=>v.kind==='pickup')){if(item.taken)continue;const d=p.distanceTo(item.mesh.position);if(d<dist){best=item;dist=d;}}const t=targetPosition(),dt=p.distanceTo(t);if(dt<dist&&dt<5)best={lead:true,name:'Investigate the lead',root:{position:t}};return best;}
