 if(nearby.horse){if(horseMounted){horseMounted=false;player.root.visible=true;player.root.position.copy(horse.root.position);player.root.position.x-=Math.sin(player.yaw)*1.5;showToast('Back on your own two feet.');}else{horseMounted=true;player.root.visible=false;horse.bond=Math.min(100,horse.bond+8);showToast('Mounted · hold SHIFT to gallop.');}return;}
 if(nearby.kind==='pickup'){nearby.taken=true;nearby.mesh.visible=false;herbs++;money+=2;refreshHud();showToast('Wild sage collected · +$2 at market');return;}
 if(nearby.enemy){showToast('That outlaw is watching your hands.');return;}
 if(nearby.lead||missionIndex===1&&nearby.role?.includes('Sheriff')){let m=currentMission(),person=nearby.keyNpc?nearby.name:'Daniel Mercer';let line=nearby.name==='Mara Bell'?m[3]:nearby.name==='Thomas Mercer'?m[3]:`${m[3]} The trail is leading west, toward the old survey road. Keep your eyes open.`;openDialogue(person,line,()=>{finishMission();});return;}
 if(nearby.name==='Mara Bell'&&missionIndex===0||nearby.name==='Silas Mercer'&&missionIndex===2||nearby.name==='June Calder'&&missionIndex===15||nearby.name==='Thomas Mercer'&&missionIndex>=18){const m=currentMission();openDialogue(nearby.name,m[3],()=>finishMission());return;}
 if(nearby.name==='Sheriff Abram Vale'){openDialogue('Sheriff Abram Vale','This is a quiet town, Mercer. It’ll stay that way if you mind your business. Now, I know what you’re here for — and I suggest you ride on.',()=>{if(missionIndex===1)finishMission();});return;}
 if(nearby.name==='Silas Mercer'||nearby.name==='June Calder'||nearby.name==='Captain Reddick'||nearby.name==='Harlan Rusk'){openDialogue(nearby.name,currentMission()[3],()=>{if(nearby.name===currentMission()[2]||nearby.lead)finishMission();});return;}
 if(nearby.role==='Shopkeeper'){openDialogue(nearby.name,'Supplies, cartridges, coffee. I take cash and don’t ask where you got it. Press 3 to use a field tonic, or come back with pelts to sell.',()=>{});return;}
 if(nearby.role==='outlaw'){showToast('An Ash Viper. You can holster your iron — or make a hard choice.');return;}
 openDialogue(nearby.name,`${nearby.name.split(' ')[0]} nods toward the western road. “Strange riders out by Red Wash. Best not go alone.”`,()=>{});
}

