function shoot(){if(!started||paused||dialogueOpen||mapOpen||inventoryOpen)return;if(fireCooldown>0)return;if(ammo<=0){showToast('Empty cylinder · press R to reload.');fireCooldown=.3;return;}ammo--;fireCooldown=.32;const origin=player.root.position.clone().add(new THREE.Vector3(0,1.7,0)),dir=new THREE.Vector3(Math.sin(player.yaw),0,Math.cos(player.yaw));dir.y=aiming?-.025:0;dir.normalize();const targets=[];for(const n of npcs){if(n.enemy&&!n.dead) n.root.traverse(o=>{if(o.isMesh)targets.push(o);});}raycaster.set(origin,dir);raycaster.far=95;const hit=raycaster.intersectObjects(targets,false)[0];let end=origin.clone().addScaledVector(dir,48);if(hit){end.copy(hit.point);const target=npcs.find(n=>n.enemy&&!n.dead&&n.root===hit.object.parent||n.enemy&&!n.dead&&n.root.children.includes(hit.object));if(target){target.health--;if(target.health<=0){target.dead=true;target.root.rotation.x=-1.25;target.root.position.y=-.2;target.root.traverse(o=>{if(o.isMesh)o.material=makeMat(0x302721);});showToast('Ash Viper down.');if(missionIndex===4){const count=npcs.filter(n=>n.enemy&&n.dead).length;if(count>=3){showToast('The camp is clear. Search the supplies.');}}}else showToast('Hit.');}else { // A frightened witness calls the law
 for(const n of npcs){if(!n.enemy&&n.root.position.distanceTo(hit.point)<18){showToast('A witness saw that. The sheriff will hear of this.');scene.userData.wanted=Math.min(5,(scene.userData.wanted||0)+1);break;}}
 }}
 const points=[origin,end],geo=new THREE.BufferGeometry().setFromPoints(points),line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xffce73,transparent:true,opacity:.9}));scene.add(line);bullets.push({mesh:line,time:.08});refreshHud();}
function reload(){const capacity=weapon?12:6,needed=capacity-ammo;if(needed<=0||reserve<=0){showToast('You’re already loaded.');return;}const take=Math.min(needed,reserve);ammo+=take;reserve-=take;showToast('Reloading…');setTimeout(refreshHud,450);}
function useTonic(){if(health>=100){showToast('You’re in fine health.');return;}health=Math.min(100,health+35);showToast('Field tonic · vitality restored.');refreshHud();}
function whistle(){if(horseMounted){showToast('Your horse is already with you.');return;}const p=player.root.position;horse.root.position.set(p.x+Math.sin(player.yaw)*2,0,p.z+Math.cos(player.yaw)*2);horse.speed=0;showToast('A long whistle carries across the open country.');}
function openMap(){if(!started)return;mapOpen=true;$('mapScreen').classList.remove('hidden');$('mapPlayer').style.left=clamp((player.root.position.x+320)/640*100,3,97)+'%';}
function closeMap(){mapOpen=false;$('mapScreen').classList.add('hidden');}
function openInventory(){if(!started)return;inventoryOpen=true;$('inventoryScreen').classList.remove('hidden');}
function closeInventory(){inventoryOpen=false;$('inventoryScreen').classList.add('hidden');}
function togglePause(){if(!started||dialogueOpen||mapOpen||inventoryOpen)return;paused=!paused;$('pauseScreen').classList.toggle('hidden',!paused);if(paused&&document.pointerLockElement)document.exitPointerLock();}
function setupEvents(){
 $('newGame').onclick=()=>startGame(false);$('continueGame').onclick=()=>startGame(true);$('mapButton').onclick=openMap;$('closeMap').onclick=closeMap;$('closeInventory').onclick=closeInventory;$('resumeButton').onclick=()=>{paused=false;$('pauseScreen').classList.add('hidden');};$('pauseMap').onclick=()=>{paused=false;$('pauseScreen').classList.add('hidden');openMap();};$('pauseInventory').onclick=()=>{paused=false;$('pauseScreen').classList.add('hidden');openInventory();};
 window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(mapOpen)closeMap();else if(inventoryOpen)closeInventory();else if(dialogueOpen){$('dialogueContinue').click();}else togglePause();}if(e.code==='KeyE')doInteract();if(e.code==='KeyM')openMap();if(e.code==='Tab')inventoryOpen?closeInventory():openInventory();if(e.code==='KeyR')reload();if(e.code==='KeyF')whistle();if(e.code==='Digit1'){weapon=0;ammo=6;reserve=Math.max(reserve,36);showToast('Frontier Revolver selected.');refreshHud();}if(e.code==='Digit2'){weapon=1;ammo=12;reserve=Math.max(reserve,48);showToast('Trail Repeater selected.');refreshHud();}if(e.code==='Digit3')useTonic();if(e.code==='Space'&&!horseMounted&&player&&player.root.position.y<=.08)player.velocityY=6.2;});
 window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('resize',()=>{if(!renderer)return;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});
 canvas.addEventListener('click',()=>{if(started&&!paused&&!dialogueOpen&&!mapOpen&&!inventoryOpen){if(!matchMedia('(pointer:coarse)').matches&&!document.pointerLockElement)canvas.requestPointerLock?.();if(keys['Mouse0'])shoot();}});
 document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&started&&!paused){player.yaw-=e.movementX*.0022;camera.userData.pitch=clamp((camera.userData.pitch||.13)-e.movementY*.0012,-.12,.52);}});
 window.addEventListener('mousedown',e=>{if(e.button===0&&started&&!paused&&!dialogueOpen&&!mapOpen&&!inventoryOpen){keys.Mouse0=true;shoot();}if(e.button===2){aiming=true;$('reticle').style.transform='translate(-50%,-50%) scale(1.35)';}});window.addEventListener('mouseup',e=>{if(e.button===0)keys.Mouse0=false;if(e.button===2){aiming=false;$('reticle').style.transform='translate(-50%,-50%)';}});window.addEventListener('contextmenu',e=>e.preventDefault());
 const base=$('stickBase'),knob=$('stickKnob');let touchId=null;const moveStick=e=>{if(touchId===null)return;const t=[...e.changedTouches].find(v=>v.identifier===touchId);if(!t)return;const r=base.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=t.clientX-cx,dy=t.clientY-cy,len=Math.hypot(dx,dy),max=33,mul=Math.min(1,max/(len||1));knob.style.transform=`translate(${dx*mul}px,${dy*mul}px)`;keys.TouchX=dx*mul/max;keys.TouchY=dy*mul/max;};base.addEventListener('touchstart',e=>{e.preventDefault();touchId=e.changedTouches[0].identifier;moveStick(e);},{passive:false});base.addEventListener('touchmove',e=>{e.preventDefault();moveStick(e);},{passive:false});const endStick=e=>{if([...e.changedTouches].some(t=>t.identifier===touchId)){touchId=null;keys.TouchX=keys.TouchY=0;knob.style.transform='';}};base.addEventListener('touchend',endStick);base.addEventListener('touchcancel',endStick);
 $('touchInteract').onclick=doInteract;$('touchFire').onpointerdown=e=>{e.preventDefault();shoot();};$('touchAim').onpointerdown=()=>aiming=true;$('touchAim').onpointerup=()=>aiming=false;$('touchJump').onclick=()=>{if(horseMounted){horse.stamina=Math.max(0,horse.stamina-12);showToast('Your horse clears the low fence.');}else if(player.root.position.y<.1)player.velocityY=6.2;};
 window.addEventListener('wheel',e=>{if(!started)return;if(e.deltaY>0){weapon=1;ammo=Math.min(ammo,12);}else{weapon=0;ammo=Math.min(ammo,6);}refreshHud();},{passive:true});
}

